def skill():
    m2, sigma = 30 + 10, 6
    return m2 + sigma

def standard():
    tbl = {1.0: Rational('0.3413'), 1.5: Rational('0.4332'), 2.0: Rational('0.4772'), 2.5: Rational('0.4938')}
    x = Symbol('x')
    m1 = solve(Eq(x - Symbol('m'), -(60 - x - Symbol('m'))), Symbol('m'))[0]
    m2 = m1 + 10
    res = []
    for k, v in tbl.items():
        tail = Rational('0.5') - v
        if 2*tail == Rational('0.3174'):
            sigma = (36 - m1) / Rational(str(k))
            res.append(m2 + sigma)
    assert len(res) == 1
    return res[0]

def unique():
    return [standard()]
